// ── 单题产出详情（后台只读视图，含内部标注与版本历史） ──

export function GetEnrichDetail(
  problemId: number,
  problemKey?: string
): Promise<CodeResult<EnrichProblemDetail>> {
  return httpRequest<unknown, CodeResult<EnrichProblemDetail>>({
    url: "/problem/enrichment/detail",
    method: "get",
    // 详情页 path 路由用 key（可读 URL）；后端对 key 有数字兜底，老入口传 id 也兼容
    params: problemKey ? { problem_key: problemKey } : { problem_id: problemId },
  });
}
